<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Tutorly — Become a tutor</title>
<script src="https://cdn.tailwindcss.com"></script>
<script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
<script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<script>
tailwind.config = {
  theme: {
    extend: {
      colors: {
        cream: '#f7f1e6',
        creamDeep: '#f3ecdf',
        forest: '#12362e',
        forestDark: '#0e2b24',
        leaf: '#7fc79a',
        leafSoft: '#dcefe2',
        ink: '#1c2b26',
        mut: '#5f6f68'
      },
      fontFamily: {
        sans: ['Poppins','sans-serif'],
        mono: ['"IBM Plex Mono"','monospace']
      }
    }
  }
}
</script>
<style>
  body{font-family:'Poppins',sans-serif;}
  .mono{font-family:'IBM Plex Mono',monospace;}
</style>
</head>
<body class="bg-cream text-ink">
<div id="root"></div>
<script type="text/babel">
const { useState } = React;

const Logo = ({className}) => (
  <div className={"flex items-center gap-2 "+(className||"")}>
    <div className="w-9 h-9 rounded-xl bg-forest flex items-center justify-center">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#7fc79a" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 10L12 5 2 10l10 5 10-5z"/><path d="M6 12v5c0 1.5 2.5 3 6 3s6-1.5 6-3v-5"/></svg>
    </div>
    <span className="text-xl font-bold text-forest">tutor<span className="text-leaf">ly</span></span>
  </div>
);

function Header(){
  return (
    <header className="w-full bg-creamDeep/80 backdrop-blur border-b border-forest/5 sticky top-0 z-40">
      <div className="max-w-[1400px] mx-auto px-8 h-[72px] flex items-center justify-between">
        <Logo/>
        <nav className="hidden md:flex items-center gap-8 ml-10">
          <a href="#" className="flex items-center gap-2 text-sm font-medium text-ink hover:text-forest transition-colors duration-150">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 015.83 1c0 2-3 3-3 3"/><circle cx="12" cy="17" r="0.5" fill="currentColor"/></svg>
            <span>Find<br className="hidden"/> tutors</span>
          </a>
          <a href="#" className="flex items-center gap-2 text-sm font-medium text-ink hover:text-forest transition-colors duration-150">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"/></svg>
            Messages
          </a>
          <a href="#" className="flex items-center gap-2 text-sm font-medium text-ink hover:text-forest transition-colors duration-150">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>
            <span>My<br/> lessons</span>
          </a>
        </nav>
        <div className="flex items-center gap-4 ml-auto">
          <div className="hidden lg:flex items-center gap-2 bg-white rounded-full px-4 py-2 w-[300px] border border-forest/10">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#5f6f68" strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg>
            <span className="text-sm text-mut flex-1">Search tutors, subjects...</span>
            <span className="mono text-[10px] border border-forest/20 rounded px-1 text-mut">⌘K</span>
          </div>
          <button className="flex items-center gap-2 bg-leafSoft border border-leaf text-forest font-semibold text-sm px-4 py-2.5 rounded-full hover:bg-leaf/40 transition-colors duration-150">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M22 10L12 5 2 10l10 5 10-5z"/></svg>
            Become a tutor
          </button>
          <a href="#" className="text-sm font-semibold text-ink hover:text-forest transition-colors duration-150">Log in</a>
          <button className="bg-forest text-white text-sm font-semibold px-5 py-2.5 rounded-full hover:bg-forestDark transition-colors duration-150">Signup</button>
        </div>
      </div>
    </header>
  );
}

function Hero(){
  const cards = [
    {icon:<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#12362e" strokeWidth="2"><rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/></svg>,
     title:"Set your own rate",
     body:"From $5 to $80 a lesson — you keep 82% of every booking; the platform takes 18%."},
    {icon:<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#12362e" strokeWidth="2"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>,
     title:"Your calendar, your pace",
     body:"Open the hours you want, teach from anywhere, close a week when life happens."},
    {icon:<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#12362e" strokeWidth="2"><path d="M22 10L12 5 2 10l10 5 10-5z"/><path d="M6 12v5c0 1.5 2.5 3 6 3s6-1.5 6-3v-5"/></svg>,
     title:"Students come to you",
     body:"Search, filters and recommendations do the matching — you just teach well."},
  ];
  return (
    <section className="pt-14 pb-4">
      <div className="flex flex-col items-center px-6">
        <span className="mono text-[11px] tracking-[0.2em] font-medium text-forest bg-leafSoft px-4 py-2 rounded-full flex items-center gap-2">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M22 10L12 5 2 10l10 5 10-5z"/></svg>
          BECOME A TUTOR
        </span>
        <h1 className="mt-6 text-center text-4xl md:text-[44px] leading-tight font-bold text-forest">Teach what you love.<br/><span className="text-forestDark">Keep 82% of it.</span></h1>
        <p className="mt-5 max-w-[560px] text-center text-[15px] leading-relaxed text-mut">Apply once, get reviewed by a human, and your profile joins the same marketplace our hand-picked tutors live in — search, bookings, messages and the live classroom included.</p>
      </div>
      <div className="max-w-[780px] mx-auto mt-10 px-6 grid md:grid-cols-3 gap-5">
        {cards.map((c,i)=>(
          <div key={i} className="bg-white rounded-2xl p-5 shadow-sm">
            <div className="w-9 h-9 rounded-lg bg-leafSoft flex items-center justify-center">{c.icon}</div>
            <h3 className="mt-4 font-semibold text-[15px] text-ink">{c.title}</h3>
            <p className="mt-2 text-[13px] leading-relaxed text-mut">{c.body}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

function DraftBar({onReset}){
  return (
    <div className="max-w-[780px] mx-auto px-6 mt-12">
      <div className="border border-dashed border-leaf rounded-2xl px-6 py-4 flex items-center justify-center gap-3 text-sm">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#12362e" strokeWidth="2" strokeLinecap="round"><path d="M20 6L9 17l-5-5"/></svg>
        <span className="text-ink">Draft restored — picking up where you left off.</span>
        <button onClick={onReset} className="ml-3 flex items-center gap-1.5 font-semibold text-forest hover:underline transition-colors duration-150">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 12a9 9 0 109-9 9.75 9.75 0 00-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>
          Start over
        </button>
      </div>
    </div>
  );
}

function Stepper({step}){
  const labels=["About you","What you teach","Your lesson","Review"];
  return (
    <div className="max-w-[780px] mx-auto px-6 mt-8">
      <div className="flex items-start">
        {labels.map((l,i)=>(
          <React.Fragment key={l}>
            <div className={"flex flex-col items-center "+(i===0?"items-start":"")}>
              <div className={"w-8 h-8 rounded-full border flex items-center justify-center text-sm font-semibold transition-colors duration-150 "+(i<step?"bg-forest text-white border-forest":i===step?"bg-white text-forest border-forest ring-4 ring-leafSoft":"bg-white text-mut border-forest/20")}>{i+1}</div>
              <span className={"mt-2 text-xs font-semibold "+(i<=step?"text-forest":"text-mut")}>{l}</span>
            </div>
            {i<labels.length-1 && <div className="flex-1 h-px bg-forest/15 mt-4 mx-4"></div>}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}

const countries=["Czechia","Slovakia","United Kingdom","Germany","Spain","Japan"];
const languages=["English","Czech","Slovak","Spanish","German","French"];

function FormCard(){
  const [first,setFirst]=useState("Nadia");
  const [last,setLast]=useState("");
  const [email,setEmail]=useState("");
  const [country,setCountry]=useState("");
  const [city,setCity]=useState("");
  const [lang,setLang]=useState("");
  const [photo,setPhoto]=useState(null);
  const [saved,setSaved]=useState("");
  const [done,setDone]=useState(false);

  const flash=(m)=>{setSaved(m);setTimeout(()=>setSaved(""),1500);};
  const onUpload=(e)=>{
    const f=e.target.files[0];
    if(f){ setPhoto(URL.createObjectURL(f)); flash("Photo attached ✓"); }
  };
  const submit=(e)=>{e.preventDefault();setDone(true);flash("Step 1 saved ✓");};

  return (
    <form onSubmit={submit} className="max-w-[780px] mx-auto px-6 mt-6 pb-16">
      <div className="bg-white rounded-2xl shadow-sm p-8">
        <p className="mono text-[11px] tracking-[0.2em] font-medium text-forest">STEP 1 OF 4</p>
        <h2 className="mt-2 text-2xl font-bold text-ink">About you</h2>
        <p className="mt-2 text-sm leading-relaxed text-mut max-w-[520px]">The basics students see first. Your email is only used to notify you about this application — it never appears on your profile.</p>

        <div className="mt-7 grid md:grid-cols-2 gap-x-8 gap-y-5">
          <div>
            <label className="block text-sm font-semibold text-ink mb-2">First name <span className="text-forest">*</span></label>
            <input value={first} onChange={e=>setFirst(e.target.value)} className="w-full border border-forest/20 rounded-lg px-4 py-3 text-sm focus:outline-none focus:border-forest transition-colors duration-150"/>
          </div>
          <div>
            <label className="block text-sm font-semibold text-ink mb-2">Last name <span className="text-forest">*</span></label>
            <input value={last} onChange={e=>setLast(e.target.value)} placeholder="e.g. Nováková" className="w-full border border-forest/20 rounded-lg px-4 py-3 text-sm placeholder-mut/70 focus:outline-none focus:border-forest transition-colors duration-150"/>
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-semibold text-ink mb-2">Email <span className="text-forest">*</span></label>
            <input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="nadia@example.com" className="w-full border border-forest/20 rounded-lg px-4 py-3 text-sm placeholder-mut/70 focus:outline-none focus:border-forest transition-colors duration-150"/>
            <p className="mt-2 text-xs text-mut">Application updates only — never shown to students.</p>
          </div>
          <div>
            <label className="block text-sm font-semibold text-ink mb-2">Country <span className="text-forest">*</span></label>
            <select value={country} onChange={e=>setCountry(e.target.value)} className="w-full border border-forest/20 rounded-lg px-4 py-3 text-sm text-mut bg-white focus:outline-none focus:border-forest transition-colors duration-150">
              <option value="">Select a country...</option>
              {countries.map(c=><option key={c}>{c}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-sm font-semibold text-ink mb-2">City <span className="text-forest">*</span></label>
            <input value={city} onChange={e=>setCity(e.target.value)} placeholder="e.g. Brno" className="w-full border border-forest/20 rounded-lg px-4 py-3 text-sm placeholder-mut/70 focus:outline-none focus:border-forest transition-colors duration-150"/>
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-semibold text-ink mb-2">Native language <span className="text-forest">*</span></label>
            <select value={lang} onChange={e=>setLang(e.target.value)} className="w-full border border-forest/20 rounded-lg px-4 py-3 text-sm text-mut bg-white focus:outline-none focus:border-forest transition-colors duration-150">
              <option value="">Select your native language...</option>
              {languages.map(l=><option key={l}>{l}</option>)}
            </select>
            <p className="mt-2 text-xs text-mut">Shown on your profile as “Native” — and it unlocks the native-speaker filter if you teach it.</p>
          </div>
        </div>

        <div className="mt-6">
          <label className="block text-sm font-semibold text-ink mb-2">Photo (optional)</label>
          <div className="border border-dashed border-leaf rounded-xl bg-cream/60 px-5 py-5 flex items-center gap-5 flex-wrap">
            {photo
              ? <img src={photo} alt="preview" className="w-16 h-16 rounded-xl object-cover"/>
              : <div className="w-16 h-16 rounded-xl bg-leafSoft flex items-center justify-center font-bold text-forest text-xl">NO</div>}
            <div className="flex-1 min-w-[200px]">
              <p className="font-semibold text-[15px] text-ink">{photo?"Looking great":"No photo yet"}</p>
              <p className="mt-1 text-[13px] leading-relaxed text-mut max-w-[420px]">A friendly headshot earns clicks. We crop it to a square automatically; no photo and your initials stand in.</p>
            </div>
            <label className="cursor-pointer flex items-center gap-2 border border-forest/20 bg-white rounded-full px-4 py-2.5 text-sm font-semibold text-forest hover:border-forest transition-colors duration-150">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.6-6 8-6s8 2 8 6"/></svg>
              Upload photo
              <input type="file" accept="image/*" className="hidden" onChange={onUpload}/>
            </label>
          </div>
        </div>

        <div className="mt-8 pt-6 border-t border-forest/10 flex items-center justify-between">
          <span className="mono text-xs text-mut">{saved || "everything saves as you type"}</span>
          {done && <span className="mono text-xs text-forest mr-auto ml-4">✓ Draft ready — continue to What you teach</span>}
          <button type="submit" className="bg-forest text-white text-sm font-semibold px-7 py-3 rounded-full hover:bg-forestDark transition-colors duration-150">Continue</button>
        </div>
      </div>
    </form>
  );
}

function Footer(){
  const cols=[
    {h:"SUBJECTS",links:["Languages","Math","Science","Programming","Music","Test prep"]},
    {h:"EXPLORE",links:["Find tutors","Become a tutor","Messages","My lessons","Practice classroom","Demo teacher room","Admin console","How it works"]},
    {h:"SUPPORT",links:["Book a trial lesson","Reschedule or cancel"]},
  ];
  return (
    <footer className="w-full bg-creamDeep/60 border-t border-forest/10 mt-10">
      <div className="max-w-[1400px] mx-auto px-8 pt-14 pb-8">
        <div className="grid md:grid-cols-[1.3fr_1fr_1fr_1fr] gap-10">
          <div>
            <Logo/>
            <p className="mt-4 text-sm leading-relaxed text-mut max-w-[300px]">1-on-1 online tutoring — languages, math, science, code and music. A portfolio build: seeded RNG data, local-only accounts, deterministic calendars.</p>
          </div>
          {cols.map(c=>(
            <div key={c.h}>
              <p className="mono text-[11px] tracking-[0.2em] text-mut">{c.h}</p>
              <ul className="mt-4 space-y-3">
                {c.links.map(l=>(
                  <li key={l}><a href="#" className="text-sm font-medium text-ink hover:text-forest transition-colors duration-150">{l}</a></li>
                ))}
                {c.h==="SUPPORT" && (
                  <li>
                    <button className="flex items-center gap-2 text-sm font-semibold text-ink hover:text-forest transition-colors duration-150" onClick={()=>{localStorage.clear();location.reload();}}>
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 12a9 9 0 109-9 9.75 9.75 0 00-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>
                      Reset demo data
                    </button>
                  </li>
                )}
              </ul>
            </div>
          ))}
        </div>
        <div className="mt-14 pt-6 border-t border-forest/10 flex flex-wrap items-center justify-between gap-3">
          <span className="text-xs text-mut">© 2026 Tutorly — a portfolio demo, not a business</span>
          <span className="mono text-[11px] text-mut">Simulated marketplace · demo card 4242 4242 4242 4242 · accounts live in localStorage</span>
        </div>
      </div>
    </footer>
  );
}

function App(){
  return (
    <div className="min-h-screen bg-cream">
      <Header/>
      <Hero/>
      <DraftBar/>
      <Stepper step={0}/>
      <FormCard/>
      <Footer/>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
</script>
</body>
</html>
```
